import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/GET-DATA-_002fTYPE_003dTXT.md","filePath":"manual-en/GET-DATA-_002fTYPE_003dTXT.md","lastUpdated":1785684581000}'),n={name:"manual-en/GET-DATA-_002fTYPE_003dTXT.md"};function d(s,e,r,T,l,f){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h4 id="_9-4-3-textual-data-files" tabindex="-1">9.4.3 Textual Data Files <a class="header-anchor" href="#_9-4-3-textual-data-files" aria-label="Permalink to &quot;9.4.3 Textual Data Files&quot;">​</a></h4><pre><code>GET DATA /TYPE=TXT
        /FILE={’file_name’,file_handle}
        [ENCODING=’encoding’]
        [/ARRANGEMENT={DELIMITED,FIXED}]
        [/FIRSTCASE={first_case}]
        [/IMPORTCASES=...]
        …additional subcommands depending on ARRANGEMENT…
</code></pre><p>When TYPE=TXT is specified, GET DATA reads data in a delimited or fixed columnar format, much like DATA LIST (see <a href="./DATA-LIST">DATA LIST</a>).</p><p>The <code>FILE</code> subcommand is mandatory. Specify the file to be read as a string file name or (for textual data only) a file handle (see <a href="./File-Handles">File Handles</a>).</p><p>The <code>ENCODING</code> subcommand specifies the character encoding of the file to be read. See <a href="./INSERT">INSERT</a>, for information on supported encodings.</p><p>The <code>ARRANGEMENT</code> subcommand determines the file’s basic format. DELIMITED, the default setting, specifies that fields in the input data are separated by spaces, tabs, or other user-specified delimiters. FIXED specifies that fields in the input data appear at particular fixed column positions within records of a case.</p><p>By default, cases are read from the input file starting from the first line. To skip lines at the beginning of an input file, set <code>FIRSTCASE</code> to the number of the first line to read: 2 to skip the first line, 3 to skip the first two lines, and so on.</p><p><code>IMPORTCASES</code> is ignored, for compatibility. Use <code>N OF CASES</code> to limit the number of cases read from a file (see <a href="./N-OF-CASES">N OF CASES</a>), or <code>SAMPLE</code> to obtain a random sample of cases (see <a href="./SAMPLE">SAMPLE</a>).</p><p>The remaining subcommands apply only to one of the two file arrangements, described below.</p><table tabindex="0"><thead><tr><th>• GET DATA /TYPE=TXT /ARRANGEMENT=DELIMITED</th><th></th><th></th></tr></thead><tbody><tr><td>• GET DATA /TYPE=TXT /ARRANGEMENT=FIXED</td><td></td><td></td></tr></tbody></table>`,10)])])}const E=t(n,[["render",d]]);export{p as __pageData,E as default};
